## Recommended Secret‑loading Pattern

Below is a **secure, production‑ready pattern** that:

1. **Uses `dotenv` only** when the app is running in a non‑production environment.
2. **Fails fast** if required secrets are missing.
3. **Encourages a secrets‑manager integration** for production (the example shows how you could pull from AWS Secrets Manager, but the same idea applies to any provider).

### 1. Install the needed packages

```bash
npm install dotenv   # for local dev only
# Optional – example for AWS Secrets Manager
npm install @aws-sdk/client-secrets-manager
```

### 2. Create a small config helper (`config.js`)

```js
// config.js
/**
 * Centralised configuration / secret loader.
 * - In development it falls back to a .env file.
 * - In production it expects the environment variables to be populated
 *   by your orchestration layer (Docker/K8s/secrets manager).
 */

const env = process.env.NODE_ENV || 'development';

// Load .env only when not in production
if (env !== 'production') {
  // eslint-disable-next-line import/no-extraneous-dependencies
  require('dotenv').config();
}

/**
 * Helper that throws a clear error if a required env var is missing.
 */
function required(key) {
  const value = process.env[key];
  if (!value) {
    throw new Error(`Missing required environment variable: ${key}`);
  }
  return value;
}

/**
 * Example: if you use AWS Secrets Manager for production,
 * you can load the secret at startup and then set process.env values.
 * This function runs once and populates process.env.
 */
async function loadAwsSecrets() {
  if (process.env.NODE_ENV !== 'production') return; // skip in dev

  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  const secretId = process.env.AWS_SECRET_ID; // e.g. "my-app/prod"

  const command = new GetSecretValueCommand({ SecretId: secretId });
  const resp = await client.send(command);
  const secretString = resp.SecretString;

  if (!secretString) {
    throw new Error(`Secret ${secretId} returned empty`);
  }

  const secretObj = JSON.parse(secretString);
  // Populate process.env – only keys you explicitly allow
  const allowed = ['DB_URI', 'JWT_SECRET', 'STRIPE_SECRET_KEY', 'HEALTH_TOKEN'];
  allowed.forEach((k) => {
    if (secretObj[k]) {
      process.env[k] = secretObj[k];
    }
  });
}

// Export the configuration values you need throughout the app
module.exports = {
  PORT: process.env.PORT || 3000,
  // Example of required secrets (will throw if missing)
  DB_URI: required('DB_URI'),               // <-- adapt to your actual DB
  JWT_SECRET: required('JWT_SECRET'),
  HEALTH_TOKEN: required('HEALTH_TOKEN'),
  // If you need to initialise async secret loading, expose the function
  loadAwsSecrets,
};
```

### 3. Wire it into `app.js`

```js
// app.js (updated)
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const {
  PORT,
  HEALTH_TOKEN,
  loadAwsSecrets,   // async loader for production secrets
} = require('./config');

const app = express();

(async () => {
  // Load secrets from the external manager *before* the server starts
  await loadAwsSecrets();

  // -----------------------------------------------------------------
  // Middleware (same as the hardened example I gave earlier)
  app.use(helmet());
  app.use(express.json());
  app.use(morgan('combined'));

  const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: { error: 'Too many requests' },
  });
  app.use('/users', apiLimiter);

  // CORS whitelist (adjust as needed)
  const allowedOrigins = ['https://my‑frontend.example.com'];
  app.use(
    cors({
      origin: (origin, cb) => {
        if (!origin || allowedOrigins.includes(origin)) cb(null, true);
        else cb(new Error('Not allowed by CORS'));
      },
      credentials: true,
    })
  );

  // -----------------------------------------------------------------
  // Routes (unchanged logic, but now uses the runtime secret)
  app.get('/health', (req, res) => {
    const token = req.get('x-health-token') || req.query.token;
    if (token !== HEALTH_TOKEN) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    // ...
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // -----------------------------------------------------------------
  // Centralised error handling
  app.use((err, _req, res, _next) => {
    console.error(err);
    const status = err.status || 500;
    const message = status === 500 ? 'Internal Server Error' : err.message;
    res.status(status).json({ error: message });
  });

  // -----------------------------------------------------------------
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });
})();
```

### What this achieves

| Benefit | How it’s enforced |
|---------|-------------------|
| **No hard‑coded secrets** – all sensitive values must exist in `process.env` (or be fetched from a manager). | `config.required()` throws on start‑up if a secret is missing. |
| **Development convenience** – `.env` files are only parsed when `NODE_ENV !== 'production'`. | `dotenv.config()` runs conditionally. |
| **Production‑grade secret sourcing** – the example shows pulling a JSON‑formatted secret from AWS Secrets Manager and whitelisting the keys you actually need. | `loadAwsSecrets()` runs *once* before the server starts. |
| **Fail‑fast** – the service will not start unless every required secret is present. | Startup error stops the process, preventing a partially‑configured service from serving traffic. |
| **Auditable central point** – all code that needs a secret imports from a *single* module, making future reviews easier. | `config.js` is the sole source of truth. |

