const { verifyToken } = require('./auth');

// Protect any route that needs a logged‑in user
app.get('/users', verifyToken, (req, res) => {
  // Only an authenticated user can hit this endpoint now
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Notes:**  
- Store `JWT_SECRET` in environment variables (never hard‑code).  
- Rotate secrets regularly, set proper `aud`/`iss` claims, and use HTTPS.

