   1️⃣ Global Middleware
   ------------------------------------------------- */

// Security HTTP headers
app.use(helmet());

// CORS – adjust the origin list as needed.
// If you only serve this API to trusted front‑ends, replace
// `*` with an explicit whitelist, e.g. ['https://myapp.example.com']
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || '*',
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

// Body parsing (JSON) with size limits – protects against oversized payloads.
app.use(express.json({ limit: '100kb' })); // Adjust limit to your use‑case

// Request logging (combined Apache format)
// In production you might pipe this to a file or a log aggregation service.
app.use(morgan('combined'));

