### 3️⃣ HashiCorp Vault – Dynamic Secrets & Lease Management

```js
// src/secrets/vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'https://vault.mycompany.com',
  token: process.env.VAULT_TOKEN, // injected via CI/CD or side‑car injection
});

/**
 * Fetch a secret from KV v2 mount.
 * Returns the parsed secret object.
 */
async function getSecret(path) {
  const result = await vault.read(`secret/data/${path}`);
  return result.data.data; // {key: value, ...}
}

// Example
(async () => {
  const db = await getSecret('prod/postgres');
  process.env.DATABASE_URL = db.url;
})();
```

*Tip*: In Kubernetes you can use the **Vault Agent Sidecar** to inject a short‑lived token, avoiding hard‑coded `VAULT_TOKEN`.

