// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

/**
 * Retrieves a secret stored as a JSON string in AWS Secrets Manager.
 * Example secret value: {"DB_PASSWORD":"s3cr3t","STRIPE_KEY":"sk_live_…"}
 */
async function loadSecrets(secretId) {
  const command = new GetSecretValueCommand({ SecretId: secretId });
  const response = await client.send(command);
  const secretString = response.SecretString;
  if (!secretString) throw new Error('Secret is empty');

  const secrets = JSON.parse(secretString);
  // Populate process.env (you may choose a different namespace instead)
  Object.entries(secrets).forEach(([k, v]) => {
    process.env[k] = v;
  });
}

