  token: process.env.VAULT_TOKEN,
});

async function loadVaultSecrets(path) {
  const result = await vault.read(path); // expects a KV v2 secret
  const data = result.data.data; // adjust for your mount version
  Object.entries(data).forEach(([k, v]) => {
    process.env[k] = v;
  });
}
module.exports = { loadVaultSecrets };
