// secrets.js  – centralised secret loader
'use strict';
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const REGION = process.env.AWS_REGION || 'us-east-1';
const client = new SecretsManagerClient({ region: REGION });

/**
 * Retrieves a secret stored as a JSON object in AWS Secrets Manager.
 * The secret name should be the same across environments (e.g. "myapp/prod").
 * Returns an object that can be merged into process.env.
 */
async function loadAwsSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  let secretString = response.SecretString;

  if (!secretString) {
    throw new Error(`Secret ${secretName} has no string value`);
  }

  // Secrets Manager often stores JSON: { "DB_PASSWORD": "...", "API_KEY": "..." }
  const secretObj = JSON.parse(secretString);
  // Populate process.env – existing values are left untouched
  Object.assign(process.env, secretObj);
  return secretObj;
}

// Export a promise that resolves when all required secrets are loaded
module.exports = async function initialiseSecrets() {
  // Example: one secret per environment (dev, test, prod) – name can be built from NODE_ENV
  const env = process.env.NODE_ENV || 'development';
  const secretName = `myapp/${env}`; // adjust to your naming scheme
  await loadAwsSecret(secretName);
};
```

