### 2.5  Authentication & Authorization (example using **express‑jwt**)

> **Note:** The current `/users` endpoint leaks personal data. Secure it behind JWT (or any auth mechanism you already use).

```js
const jwt = require('express-jwt');          // npm i express-jwt jsonwebtoken
const jwksRsa = require('jwks-rsa');         // npm i jwks-rsa

// Example: use Auth0 JWKS endpoint (replace with your own issuer)
const checkJwt = jwt({
  secret: jwksRsa.expressJwtSecret({
    cache: true,
    rateLimit: true,
    jwksRequestsPerMinute: 5,
    jwksUri: process.env.JWKS_URI,
  }),
  audience: process.env.JWT_AUDIENCE,
  issuer: process.env.JWT_ISSUER,
  algorithms: ['RS256'],
});

app.get('/users', checkJwt, (req, res) => {
  // req.user now contains JWT claims, can be used for RBAC
  res.json([...]);
});
```

If you don’t have a JWT infrastructure yet, a simple session‑based guard can be added:

```js
const basicAuth = require('basic-auth');   // npm i basic-auth

function requireAuth(req, res, next) {
  const credentials = basicAuth(req);
  if (!credentials || credentials.name !== process.env.ADMIN_USER ||
      credentials.pass !== process.env.ADMIN_PASS) {
    res.set('WWW-Authenticate', 'Basic realm="User Visible Realm"');
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

app.get('/users', requireAuth, (req, res) => { ... });
```

**Why:**  
- Prevents unauthenticated enumeration of user data (A2, A5).  
- Enables future role‑based access control (RBAC) (A5).

