Below is a **single, ready‑to‑run** version that incorporates all the above hardening measures (excluding optional JWT config you may adapt). Feel free to copy‑paste and adjust environment variables as needed.

```js
// app.js – hardened starter template
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const winston = require('winston');
const basicAuth = require('basic-auth');
// const { celebrate, Joi, errors } = require('celebrate'); // uncomment when you need validation

const app = express();

// ---------- Security Middleware ----------
app.use(helmet());
app.disable('x-powered-by');

const allowedOrigins = (process.env.CORS_ORIGINS || '')
  .split(',')
  .filter(Boolean);
app.use(
  cors({
    origin: (origin, callback) => {
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// ---------- Logging ----------
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.Console()],
});
app.use(
  morgan('combined', {
    stream: { write: (msg) => logger.info(msg.trim()) },
  })
);

// ---------- Rate Limiting ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // protect any future sensitive endpoint

// ---------- Simple Auth (replace with JWT/OPA as needed) ----------
function requireAuth(req, res, next) {
  const credentials = basicAuth(req);
  const user = process.env.ADMIN_USER;
  const pass = process.env.ADMIN_PASS;
  if (
    !credentials ||
    credentials.name !== user ||
    credentials.pass !== pass
  ) {
    res.set('WWW-Authenticate', 'Basic realm="Restricted Area"');
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', requireAuth, (req, res) => {
  // Minimal data – no PII unless caller is authorized to see it
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ---------- Central Error Handler ----------
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { message: err.message, stack: err.stack });
  const status = err.status || 500;
  const safeMessage = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: safeMessage });
});

// ---------- Server (HTTP or HTTPS) ----------
const http = require('http');
const https = require('https');
const fs = require('fs');

const PORT = process.env.PORT || 3000;
const ENABLE_HTTPS = process.env.ENABLE_HTTPS === 'true';

if (ENABLE_HTTPS) {
  const httpsOptions = {
    key: fs.readFileSync(process.env.TLS_KEY_PATH, 'utf8'),
    cert: fs.readFileSync(process.env.TLS_CERT_PATH, 'utf8'),
    // ca: fs.readFileSync(process.env.TLS_CA_PATH, 'utf8'), // optional
  };
  https.createServer(httpsOptions, app).listen(PORT, () => {
    logger.info(`HTTPS server listening on port ${PORT}`);
  });
} else {
  app.listen(PORT, () => {
    logger.info(`HTTP server listening on port ${PORT}`);
  });
}

module.exports = app;
```

