## 1️⃣  Choose a Secrets Manager (example: **AWS Secrets Manager**)

> *If you are on another cloud or on‑prem, the same pattern applies – just swap the SDK/client.*

```bash
# Install the AWS SDK (v3) – supports Secrets Manager
npm i @aws-sdk/client-secrets-manager
```

### 1.1  Minimal wrapper to fetch a secret at runtime

Create a new file `secrets.js` (or `config.js`) that lazily loads secrets the first time they are requested:

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const REGION = process.env.AWS_REGION || 'us-east-1';   // this may still be in the environment (non‑secret)
const client = new SecretsManagerClient({ region: REGION });

/**
 * Retrieves a secret value from AWS Secrets Manager.
 * Caches the secret in memory for the lifetime of the process.
 *
 * @param {string} secretName - The name/ARN of the secret.
 * @returns {Promise<string|object>} Parsed JSON secret or plain string.
 */
const cache = {};

async function getSecret(secretName) {
  if (cache[secretName]) return cache[secretName];

  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  let secret = response.SecretString;

  try {
    secret = JSON.parse(secret); // many teams store a JSON object per secret
  } catch (_) {
    // Keep as raw string if JSON parse fails
  }

  cache[secretName] = secret;
  return secret;
}

module.exports = { getSecret };
```

### 1.2  Use the wrapper in **app.js**

```js
// app.js (excerpt)
// -------------------------------------------------
const { getSecret } = require('./secrets');

// Example: fetch a DB connection string and an admin password
async function loadSecrets() {
  const dbSecret = await getSecret('myapp/database');      // stores {host,username,password,dbname}
  const adminCreds = await getSecret('myapp/adminCreds'); // stores {user,pass}
  return { dbSecret, adminCreds };
}

// -------------------------------------------------
(async () => {
  const { dbSecret, adminCreds } = await loadSecrets();

  // Use the values wherever needed
  const ADMIN_USER = adminCreds.user;
  const ADMIN_PASS = adminCreds.pass;

  // Example: protect the /users route with the loaded credentials
  function requireAuth(req, res, next) {
    const credentials = basicAuth(req);
    if (!credentials ||
        credentials.name !== ADMIN_USER ||
        credentials.pass !== ADMIN_PASS) {
      res.set('WWW-Authenticate', 'Basic realm="Restricted Area"');
      return res.status(401).json({ error: 'Unauthorized' });
    }
    next();
  }

  // Register routes *after* the secrets are loaded
  app.get('/users', requireAuth, (req, res) => {
    // …return data…
  });

  // Start the server (same as before)
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`Server listening on ${PORT}`));
})();
```

**What changed?**

* **No `.env` file** is required for the privileged values (`ADMIN_USER`, `ADMIN_PASS`, DB passwords, TLS private keys, etc.).  
* Secrets are fetched **once per process** and cached, limiting API calls to the secrets manager.  
* The rest of the code stays exactly the same – you only replace `process.env.*` look‑ups with the values returned from `getSecret`.

