## 2️⃣  If you *must* keep a fallback `.env` for non‑secret config

You can still use `dotenv` for **non‑sensitive** configuration (port numbers, feature flags, log levels). Keep the file **out of source control** (`.gitignore`) and *never* store passwords or private keys there.

```bash
# .gitignore (add this if it isn’t already present)
.env
```

```js
// config.js – thin wrapper that prefers secret‑manager values
require('dotenv').config();               // loads ONLY non‑secret env vars

const { getSecret } = require('./secrets');

async function loadConfig() {
  // Non‑secret fallback via .env
  const PORT = process.env.PORT || 3000;
  const ENABLE_HTTPS = process.env.ENABLE_HTTPS === 'true';

  // Secrets (must exist in the manager, otherwise app will crash at start‑up)
  const tls = await getSecret('myapp/tls');          // {keyPath, certPath, maybe PEM strings}
  const admin = await getSecret('myapp/adminCreds'); // {user, pass}

  return {
    PORT,
    ENABLE_HTTPS,
    TLS_KEY_PATH: tls.keyPath,
    TLS_CERT_PATH: tls.certPath,
    ADMIN_USER: admin.user,
    ADMIN_PASS: admin.pass,
  };
}

module.exports = { loadConfig };
```

Now `app.js` can simply:

```js
const { loadConfig } = require('./config');

(async () => {
  const cfg = await loadConfig();
  // use cfg.PORT, cfg.ADMIN_USER, etc.
})();
```

