## 🔐 Detailed Review & Fixes

### 1️⃣ Add Core Security Middleware (Helmet, CORS, CSP)

```js
// ---- security.js -------------------------------------------------
const helmet = require('helmet');
const cors    = require('cors');

// Basic Helmet (sets dozens of security headers)
const helmetMiddleware = helmet();

// Optional CSP – adjust the directives to suit your front‑end
const cspMiddleware = helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc:  ["'self'"],
    styleSrc:   ["'self'", 'https:'],
    imgSrc:     ["'self'", 'data:'],
    connectSrc:["'self'"],
    // add others as needed
  },
});

// CORS – restrict origins in production
const corsMiddleware = cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET','POST','PUT','DELETE','OPTIONS'],
  credentials: true,
});

module.exports = { helmetMiddleware, cspMiddleware, corsMiddleware };
```

Add it to the main app:

```js
// app.js
const express = require('express');
const { helmetMiddleware, cspMiddleware, corsMiddleware } = require('./security');

const app = express();

app.use(helmetMiddleware);
app.use(cspMiddleware);
app.use(corsMiddleware);
```

**Why?**  
Helmet adds `X‑Content-Type-Options`, `X‑Frame-Options`, `Strict-Transport-Security`, `X‑XSS‑Protection`, etc. CORS prevents browsers from letting other origins read your API. CSP mitigates XSS in case you ever serve HTML.

---

### 2️⃣ Enforce HTTPS (Redirect + HSTS)

```js
// Force HTTPS in production (placed early in middleware stack)
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.secure) {
      return next();
    }
    // 307 preserves method and body
    res.redirect(307, `https://${req.headers.host}${req.originalUrl}`);
  });
}
```

If you terminate TLS at a reverse proxy (NGINX, Cloudflare, etc.), you can just set `app.set('trust proxy', 1);` so `req.secure` works correctly.

---

### 3️⃣ Rate‑Limiting (DoS Mitigation)

```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});

app.use('/users', apiLimiter); // apply only to sensitive routes
// or app.use(apiLimiter); // apply globally
```

**Why?** Prevents brute‑force, credential stuffing and accidental overload.

---

### 4️⃣ Authentication & Authorization

**Example using JWT (jsonwebtoken) + a simple role check**

```js
// auth.js ---------------------------------------------------------
const jwt = require('jsonwebtoken');

const secret = process.env.JWT_SECRET || 'CHANGE_THIS_IN_PROD';

// Middleware: verify token
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, secret);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Middleware: authorize based on role
function authorize(allowedRoles = []) {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}

module.exports = { authenticate, authorize };
```

Secure the `/users` endpoint:

```js
const { authenticate, authorize } = require('./auth');

app.get(
  '/users',
  authenticate,
  authorize(['admin', 'support']),   // only these roles may list users
  (req, res) => {
    // Ideally pull users from DB, filter sensitive fields, etc.
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  }
);
```

**Why?** Implements OWASP A02 – Broken Authentication & A07 – Identification & Authentication.

---

### 5️⃣ Input Validation & Sanitisation (Future‑Proof)

If you ever add POST/PUT endpoints, use a validator:

```js
const { body, param, validationResult } = require('express-validator');

// Example: create a new user
app.post(
  '/users',
  authenticate,
  authorize(['admin']),
  [
    body('name').trim().isLength({ min: 1, max: 100 }).escape(),
    body('email').isEmail().normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // safe to use req.body now …
    res.status(201).json({ message: 'User created' });
  }
);
```

**Why?** Prevents injection attacks (A01 – Injection) and ensures data integrity.

---

### 6️⃣ Centralised Error Handling & Logging

```js
const morgan = require('morgan');
const winston = require('winston');

// Simple request logger (dev mode) – replace with winston for production
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Catch async errors (requires Node 14+ or a wrapper like express-async-errors)
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1); // crash‑fast
});

// Error‑handling middleware (must be after all routes)
app.use((err, req, res, next) => {
  console.error(err); // or use winston
  const status = err.status || 500;
  const response = { error: status === 500 ? 'Internal Server Error' : err.message };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});
```

**Why?** Prevents leaking stack traces to the client (A03 – Sensitive Data Exposure) and gives you a central place to log anomalies.

---

### 7️⃣ Health Endpoint – Minimal Information

```js
app.get('/health', (req, res) => {
  // No timestamp or internal details unless you need them
  res.json({ status: 'ok' });
});
```

If you need to expose metrics, protect the endpoint with a static token or restrict to internal IP ranges.

