### 2.2 Re‑write `app.js` with Security Middleware  

```js
// app.js - Hardened version
require('dotenv').config();               // <-- Load .env (never commit .env to repo)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, param, validationResult } = require('express-validator');

const app = express();

/* -------------------------------------------------
   1️⃣ Global Security Middleware
   ------------------------------------------------- */
// Remove Express default header (information leakage)
app.disable('x-powered-by');

// Helmet adds many security headers (CSP, HSTS, X‑Frame‑Options, etc.)
app.use(helmet());

// Tight CORS policy – adapt `origin` to your client domain(s)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [], // e.g. "https://myapp.com"
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true
}));

// Rate limiting (per IP) – adjust limits to your traffic profile
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // max 100 requests per window per IP
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/users', apiLimiter);   // apply to the sensitive route
app.use('/health', apiLimiter);  // optional, to avoid health‑check abuse

// Request logging (use a rotating file or external log service in prod)
app.use(morgan('combined'));

/* -------------------------------------------------
   2️⃣ Body parser & validation utilities
   ------------------------------------------------- */
// If you later add POST/PUT routes, enable JSON body parsing:
app.use(express.json());   // parses application/json
app.use(express.urlencoded({ extended: false })); // parses application/x-www-form-urlencoded

/* -------------------------------------------------
   3️⃣ Routes
   ------------------------------------------------- */

/**
 * GET /health
 * Simple liveness probe – no auth needed.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * **Protected endpoint** – require an API key / JWT (example below).
 *
 * Example auth for demo: a static header `x-api-key` from .env.
 * Replace with proper JWT auth in production.
 */
const requireApiKey = (req, res, next) => {
  const suppliedKey = req.header('x-api-key');
  const validKey = process.env.API_KEY; // set in .env
  if (!validKey || suppliedKey !== validKey) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};

app.get(
  '/users',
  requireApiKey,
  // Example validation (if you later support query params like ?limit=10)
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
  ],
  (req, res) => {
    // Validate query params
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app you would fetch from DB. Here we keep the static list.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Optionally honour a paging limit
    const limit = req.query.limit;
    const payload = limit ? users.slice(0, limit) : users;

    res.json(payload);
  }
);

/* -------------------------------------------------
   4️⃣ Centralized error handling
   ------------------------------------------------- */
app.use((err, req, res, next) => {
  // Log the error – in production, forward to a logging service
  console.error(err);
  res
    .status(err.status || 500)
    .json({ error: err.message || 'Internal Server Error' });
});

/* -------------------------------------------------
   5️⃣ Server start (use environment‑controlled port)
   ------------------------------------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

