### 3.2 Example: AWS Secrets Manager

**Prerequisites**

```bash
npm install @aws-sdk/client-secrets-manager
```

**Implementation (`lib/awsSecrets.js`)**

```js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Retrieve a secret from AWS Secrets Manager.
 * The secret name is the logical name you pass (e.g., "API_KEY").
 */
async function fetchAwsSecret(name) {
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);
  if (!response.SecretString) {
    throw new Error(`Secret ${name} has no string value`);
  }
  return response.SecretString;
}

module.exports = { fetchAwsSecret };
```

**Wire it into `lib/secrets.js` (prod branch):**

```js
// ... other imports
const { fetchAwsSecret } = require('./awsSecrets');

async function getSecret(name) {
  if (!isProduction) {
    const val = process.env[name];
    if (!val) throw new Error(`Missing dev secret: ${name}`);
    return val;
  }
  // Production → AWS
  return await fetchAwsSecret(name);
}
```

**IAM Requirement** – The EC2/ARN (or Lambda) role that runs the app must have `secretsmanager:GetSecretValue` permission for the secret(s) it needs.

