### 3.3 Example: Azure Key Vault

**Prerequisites**

```bash
npm install @azure/keyvault-secrets @azure/identity
```

**Implementation (`lib/azureSecrets.js`)**

```js
const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');

const credential = new DefaultAzureCredential();
const vaultUrl = process.env.AZURE_KEYVAULT_URL;   // e.g., https://myvault.vault.azure.net/
const client = new SecretClient(vaultUrl, credential);

async function fetchAzureSecret(name) {
  const secret = await client.getSecret(name);
  if (!secret.value) {
    throw new Error(`Azure Key Vault secret ${name} is empty`);
  }
  return secret.value;
}

module.exports = { fetchAzureSecret };
```

**Wire it into `lib/secrets.js`** (replace the AWS call with `fetchAzureSecret`).  
The runtime identity (Managed Identity, Service Principal, etc.) must have the **Key Vault Secrets User** role on the vault.

---

### 3.4 Example: HashiCorp Vault (HTTP API)

**Prerequisites**

```bash
npm install node-vault
```

**Implementation (`lib/vaultSecrets.js`)**

```js
const vault = require('node-vault')({
  apiVersion: 'v1',                     // default
  endpoint: process.env.VAULT_ADDR,     // e.g., https://vault.mycorp.com
  token: process.env.VAULT_TOKEN,       // ideally injected via a side‑car or instance profile
});

async function fetchVaultSecret(name) {
  // Assuming KV‑v2 mount at "secret/"
  const result = await vault.read(`secret/data/${name}`);
  const value = result?.data?.data?.value;
  if (!value) throw new Error(`Vault secret ${name} not found`);
  return value;
}

module.exports = { fetchVaultSecret };
```

**Wire it into `lib/secrets.js`** similarly.  
Vault token should be **auto‑renewed** (e.g., via AppRole or Kubernetes auth) and never hard‑coded.

