const express = require('express');
const helmet = require('helmet');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ------------------------------------------------------------------
// 1. Generic security hardening
// ------------------------------------------------------------------
app.set('trust proxy', 1);               // needed when behind a reverse proxy (e.g., Heroku)
app.disable('x-powered-by');            // hide Express version
app.use(helmet());                       // sets many secure headers (CSP, HSTS, etc.)

// Example: Tighten CSP (adjust sources as needed)
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:'],
    },
  })
);

// ------------------------------------------------------------------
// 2. Logging & request parsing
// ------------------------------------------------------------------
app.use(morgan('combined'));            // Apache‑style logging (can pipe to Winston)
app.use(express.json());                // Parse JSON bodies (needed for future POST/PUT)
app.use(express.urlencoded({ extended: false }));

// ------------------------------------------------------------------
// 3. CORS (restrict to trusted origins)
// ------------------------------------------------------------------
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow non‑browser requests (e.g., curl, postman) when origin is undefined
      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
  })
);

// ------------------------------------------------------------------
// 4. Rate limiting (public endpoints)
// ------------------------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/health', apiLimiter);
app.use('/users', apiLimiter); // still limited even after auth is added

// ------------------------------------------------------------------
// 5. Authentication middleware (JWT)
// ------------------------------------------------------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // attach user info to request
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
