// 6. Input validation helper (express‑validator)
// ------------------------------------------------------------------
const handleValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Fail‑fast – give detailed but safe error messages
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ------------------------------------------------------------------
// 7. Routes
// ------------------------------------------------------------------
