(async () => {
  const secrets = await getSecret('projects/my-project/secrets/app-config/versions/latest');
  const JWT_SECRET = secrets.JWT_SECRET;
  // continue bootstrapping …
})();
```

#### C. HashiCorp Vault (Node.js)

```js
// vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN,
});

async function getSecrets(path = 'secret/data/app') {
  const result = await vault.read(path);
  // Vault KV v2 stores data under result.data.data
  return result.data?.data || {};
}

module.exports = { getSecrets };
```

```js
