// Auth middleware (uses the async‑loaded JWT secret)
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// ----------------------------------------------------------
// Routes (identical to previous version)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ----------------------------------------------------------
// Generic error handler
app.use((err, req, res, next) => {
  console.error(err);
  const status = err.status || 500;
  const msg = NODE_ENV === 'production' ? 'Internal server error' : err.message;
  res.status(status).json({ error: msg });
});

// ----------------------------------------------------------
// Start server (only after JWT secret has been set)
function startServer() {
  if (!JWT_SECRET) {
    // In case the async secret loader hasn't finished yet
    setTimeout(startServer, 100);
    return;
  }
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${NODE_ENV})`);
  });
}
startServer();

module.exports = app;
```

