    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  }));

  // 3️⃣ Rate limiting – 100 requests per 15‑minute window per IP
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: { error: 'Too many requests, please try again later.' },
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);

  // 4️⃣ Request logging (use a more robust logger in production)
  app.use(morgan('combined'));
};
```

