## 2. Protect Sensitive Endpoints (Authentication & Authorization)

### 2.1 Add JWT‑based authentication middleware

Create a reusable auth module:

```js
// auth.js  (new file)
const jwt = require('jsonwebtoken');

// Use a strong secret stored outside source code (environment variable or secret manager)
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_IN_PROD';

function generateToken(payload, expiresIn = '1h') {
  return jwt.sign(payload, JWT_SECRET, { expiresIn });
}

// Middleware to verify token and attach the decoded user to request
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const user = jwt.verify(token, JWT_SECRET);
    req.user = user; // e.g., { id, role, ... }
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Simple role‑based access check (extend as needed)
function authorize(allowedRoles = []) {
  return (req, res, next) => {
    if (!req.user) return res.status(401).json({ error: 'Unauthenticated' });
    if (allowedRoles.length && !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}

module.exports = { generateToken, authenticate, authorize };
```

### 2.2 Secure the `/users` endpoint

```js
// app.js (add near the top)
const { authenticate, authorize } = require('./auth');

// Only admin users may list all users
app.get('/users', authenticate, authorize(['admin']), (req, res) => {
  // In a real app fetch from DB, never expose e‑mail unless needed.
  // Example: hide PII for non‑admin callers.
  const users = [
    { id: 1, name: 'Alice' /* email omitted */ },
    { id: 2, name: 'Bob'   /* email omitted */ },
  ];
  res.json(users);
});
```

**Result:** Anonymous callers receive a **401 Unauthorized**, preventing the leakage of PII. You can also implement finer‑grained access by returning only the authenticated user’s own record.

