const { authenticate, authorize } = require('./auth');

app.post(
  '/users',
  authenticate,
  authorize(['admin']),
  validateBody(createUserSchema),
  async (req, res, next) => {
    try {
      // Use a parameterised query / ORM – never concatenate strings!
      const newUser = await db.User.create(req.validated);
      res.status(201).json({ id: newUser.id });
    } catch (e) {
      next(e);
    }
  }
);
```

**Key take‑aways**

| Validation technique | Why it matters |
|----------------------|----------------|
| Use a **whitelist schema** (e.g., Joi) | Prevents injection, type‑confusion, and over‑posting attacks. |
| Validate *both* query parameters and request bodies | Every attack surface is covered. |
| Reject requests with a **400 Bad Request** before reaching DB/OS | Reduces load and eliminates unsafe data early. |

