  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /api/users – protected endpoint (only authenticated users)
 * Returns only non‑sensitive fields. Email is redacted unless the caller has the "admin" role.
 */
app.get('/api/users', authMiddleware, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Example RBAC: only admins see email
  const safeUsers = users.map(u => ({
    id: u.id,
    name: u.name,
    ...(req.user.role === 'admin' && { email: u.email })
  }));
  res.json(safeUsers);
});

/**
 * Example POST /api/users – demonstrates input validation & sanitisation
 */
app.post(
  '/api/users',
  authMiddleware,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be 2–100 characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // At this point inputs are safe. Insert into DB / etc.
    const { name, email } = req.body;
    // Fake response:
    res.status(201).json({ id: Date.now(), name, email });
  }
);

// ---------- 5️⃣ GLOBAL ERROR HANDLER ----------
app.use((err, req, res, next) => {
  console.error(err); // could be replaced by winston logger
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// ---------- 6️⃣ SERVER START ----------
