 * In non‑production environments it falls back to `dotenv` for convenience.
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const fs = require('fs');
const path = require('path');

const isProd = process.env.NODE_ENV === 'production';

if (!isProd) {
  // Load .env only for local/dev – never in prod
  const dotenvPath = path.resolve(process.cwd(), '.env');
  if (fs.existsSync(dotenvPath)) {
    require('dotenv').config({ path: dotenvPath });
  }
}

/**
 * Fetch a secret value.
 *
 * @param {string} secretName   The name/ARN of the secret in AWS Secrets Manager.
 * @returns {Promise<string>}   The secret string (or JSON‑parsed object if needed).
 */
async function getSecret(secretName) {
  if (!isProd) {
    // Development shortcut: read from environment variables (populated by dotenv)
    if (process.env[secretName]) {
      return process.env[secretName];
    }
    throw new Error(`Missing env var ${secretName} (development mode)`);
  }

  // ---------- Production path ----------
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);

  if (!response.SecretString) {
    throw new Error(`Secret ${secretName} has no string value`);
  }

  // If you store JSON (e.g., `{ "username":"admin", "password":"p@ss" }`) you can parse here:
  // return JSON.parse(response.SecretString);
  return response.SecretString;
}

/**
 * Helper to bulk‑load a set of required secrets at startup.
 *
 * Example usage:
 *   const { DB_URL, JWT_SECRET } = await loadSecrets({
 *     DB_URL: 'myapp/database_url',
 *     JWT_SECRET: 'myapp/jwt_secret'
 *   });
 */
async function loadSecrets(map) {
  const result = {};
  for (const [envVar, secretId] of Object.entries(map)) {
    result[envVar] = await getSecret(secretId);
  }
  return result;
}

module.exports = { getSecret, loadSecrets };
```

### 4️⃣ Wire the loader into **app.js**

```js
// app.js – updated to use the secret loader
require('dotenv').config({ path: '.env' }); // optional: keep for local dev only
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { loadSecrets } = require('./config/secrets');

const app = express();

(async () => {
  // ------- Load required secrets (runs once at startup) ----------
  const {
    JWT_SECRET,
    DATABASE_URL,          // example: needed if you add a DB later
    STRIPE_SECRET_KEY,
    ANTHROPIC_API_KEY,
    // add any other secret identifiers you need
  } = await loadSecrets({
    JWT_SECRET:          'myapp/jwt_secret',            // secret name in AWS Secrets Manager
    DATABASE_URL:        'myapp/database_url',
    STRIPE_SECRET_KEY:   'myapp/stripe_secret_key',
    ANTHROPIC_API_KEY:   'myapp/anthropic_api_key',
  });

  // -------------------------------------------------
  // Global Middleware
  // -------------------------------------------------
  app.use(helmet());
  app.disable('x-powered-by');
  app.use(express.json());
  app.use(cors({
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    credentials: true,
    methods: ['GET', 'POST']
  }));
  app.use(rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  }));
  app.use(morgan('combined'));

  // -------------------------------------------------
  // Auth middleware (uses the secret we just loaded)
  // -------------------------------------------------
  const authenticate = (req, res, next) => {
    const authHeader = req.headers.authorization;
    if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

    const token = authHeader.split(' ')[1];
    try {
      const payload = jwt.verify(token, JWT_SECRET);
      req.user = payload;
      next();
    } catch (e) {
      return res.status(401).json({ error: 'Invalid token' });
    }
  };

  // -------------------------------------------------
  // Routes (unchanged – demo only)
  // -------------------------------------------------
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', authenticate, (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // -------------------------------------------------
  // Global error handler
  // -------------------------------------------------
  app.use((err, _req, res, _next) => {
    console.error(err);
    const status = err.status || 500;
    const msg = process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message;
    res.status(status).json({ error: msg });
  });

  // -------------------------------------------------
  // Start the server
  // -------------------------------------------------
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
})().catch(err => {
  console.error('Failed to start application – secret load error:', err);
  process.exit(1);
});

module.exports = app;
```

**Key points in this implementation**

* **Production path** – secrets are retrieved *once* at startup from AWS Secrets Manager (or whichever provider you configure). They are stored **only in memory**, never written to disk.
* **Development path** – `dotenv` is still used for convenience, **but only when `NODE_ENV !== 'production'`**. That isolates the dangerous file‑based loading to local dev environments.
* The secret‑loader is **centralised**, so any future secret (e.g., a DB connection string) can be added by extending the `loadSecrets` call.
* No `.env` files are required in the Docker image or on the host in production, eliminating the risk of a secret file being leaked through an image layer.

### 5️⃣ Deploy‑time Secret Injection (Kubernetes example)

If you run the app in Kubernetes, you can avoid the SDK call altogether and let the orchestrator mount the secrets as environment variables:

```yaml
apiVersion: v1
kind: Secret
metadata:
  name: myapp-secrets
type: Opaque
stringData:
  JWT_SECRET:        <base64‑encoded‑value>
  DATABASE_URL:     postgres://admin:…@db.internal:5432/production
  STRIPE_SECRET_KEY: sk_live_…
  ANTHROPIC_API_KEY: sk-ant-…

---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: myapp
spec:
  template:
    spec:
      containers:
        - name: server
          image: myrepo/myapp:latest
          envFrom:
            - secretRef:
                name: myapp-secrets
          # No .env file is ever baked into the container.
```

The **same `app.js`** works without any code changes because the secrets appear in `process.env` automatically.

### 6️⃣ Auditing & Rotation

| Tool | What it does |
|------|--------------|
| **AWS Secrets Manager** – automatic rotation (set a Lambda to rotate every 30 days). |
| **Git hooks** – use `pre‑commit` or `husky` to reject commits containing `AWS_SECRET_ACCESS_KEY`, `STRIPE_SECRET_KEY`, etc. |
| **Secret scanning CI** – enable GitHub secret scanning or run `detect-secrets` in your pipeline. |
| **Logging** – never log the secret values. In the code above we only log errors, not the secret itself. |

