## 📦 Minimal Hardened Version

Below is a **drop‑in** rewrite that addresses the most critical items while staying readable. You can copy‑paste this over the current file (or keep the original and require this as a separate module).

```js
// app.js – Hardened example
// ----------------------------------------------------
// Dependencies
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const jwt = require('jsonwebtoken'); // example JWT auth
require('dotenv').config(); // Loads .env (PORT, JWT_SECRET, etc.)

const app = express();

// -------------------
// 1. Basic security hardening
// -------------------
app.disable('x-powered-by');                     // Remove framework fingerprint
app.use(helmet());                              // Sets CSP, HSTS, X‑Frame‑Options, etc.
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      // Add more as needed (e.g., imgSrc, styleSrc)
    },
  })
);
app.use(cors({                                 // Change origin in production
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json({ limit: '10kb' }));       // Body‑size limit (prevents DoS)
app.use(morgan('combined'));                    // Request logging

// -------------------
// 2. Rate limiting (prevents brute‑force & DoS)
// -------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// -------------------
// 3. Simple JWT auth middleware (replace with your auth strategy)
// -------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing token' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // attach user info for RBAC later
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// -------------------
// 4. Routes
// -------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users – protected endpoint.
 * In a real app you'd pull data from a DB with parameterised queries.
 */
app.get('/users', authenticate, (req, res) => {
  // Example RBAC check (only admin can view full list)
  if (!req.user.roles?.includes('admin')) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Static data for demo – in production replace with DB call
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// -------------------
// 5. Centralised error handler (no stack traces in prod)
// -------------------
app.use((err, _req, res, _next) => {
  // Log the error (could be sent to Sentry, Logstash, etc.)
  console.error(err);
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

// -------------------
// 6. Server start – use env var for port, default to 3000
// -------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

